//! Parity with NumPy (`numpy.fft.fft`, `rfft`) on small fixtures regenerated by hand with `tools/teoria_riferimento.py`.

use ftir_core::didactic::apodization::Apodization;
use ftir_core::didactic::fft::fft;
use ftir_core::didactic::interferogram::Interferogram;
use ftir_core::didactic::spectrum::{spectrum_from_interferogram, Options, Output};
use ftir_core::passi::json::{parse, Value};

const TOLERANCE: f64 = 1e-9;

fn floats(v: &Value, key: &str) -> Vec<f64> {
    v.get(key)
        .and_then(Value::as_arr)
        .unwrap()
        .iter()
        .map(|x| x.as_f64().unwrap())
        .collect()
}

fn fixture() -> Value {
    parse(include_str!("fixture/didactic/parity.json")).unwrap()
}

#[test]
fn fft_matches_numpy() {
    let data = fixture();
    let cases = data.get("fft").and_then(Value::as_arr).unwrap();
    assert!(cases.len() >= 5);
    for case in cases {
        let (mut re, mut im) = (floats(case, "re"), floats(case, "im"));
        fft(&mut re, &mut im).unwrap();
        let (er, ei) = (floats(case, "fft_re"), floats(case, "fft_im"));
        for k in 0..re.len() {
            assert!((re[k] - er[k]).abs() <= TOLERANCE, "n={} re[{k}]", re.len());
            assert!((im[k] - ei[k]).abs() <= TOLERANCE, "n={} im[{k}]", re.len());
        }
    }
}

#[test]
fn spectrum_matches_numpy() {
    let data = fixture();
    for case in data.get("spectrum").and_then(Value::as_arr).unwrap() {
        let f = |k: &str| case.get(k).and_then(Value::as_f64).unwrap();
        let s = |k: &str| case.get(k).and_then(Value::as_str).unwrap();
        let half = f("half_points") as usize;
        let ifg = Interferogram {
            step_cm: f("step_cm"),
            zpd_index: half,
            intensity: floats(case, "intensity"),
        };
        let opts = Options {
            opd_max_cm: f("opd_max_cm"),
            apodization: Apodization::from_id(s("apodization")).unwrap(),
            zero_fill: f("zero_fill") as usize,
            output: if s("output") == "real" {
                Output::Real
            } else {
                Output::Magnitude
            },
        };
        let got = spectrum_from_interferogram(&ifg, &opts).unwrap().intensity;
        let want = floats(case, "expected");
        assert_eq!(got.len(), want.len(), "{}", s("apodization"));
        for (k, (a, b)) in got.iter().zip(&want).enumerate() {
            assert!(
                (a - b).abs() <= TOLERANCE,
                "{} [{k}]: {a} vs {b}",
                s("apodization")
            );
        }
    }
}
